-- Catálogos oficiales SAT Carta Porte 3.1. Fuente: CatalogosCartaPorte31.xls (SAT), publicado 17/06/2024.
-- Migración autosuficiente e idempotente; no elimina ni trunca registros.
BEGIN;
CREATE SCHEMA IF NOT EXISTS sat;
CREATE TABLE IF NOT EXISTS sat.bienes_transportados (
  clave_prod_serv_cp varchar(20) PRIMARY KEY, descripcion text NOT NULL, palabras_similares text NULL,
  material_peligroso varchar(3) NULL, fecha_inicio_vigencia date NULL, fecha_fin_vigencia date NULL
);
CREATE TABLE IF NOT EXISTS sat.materiales_peligrosos (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, clave_material_peligroso_sat varchar(20) NOT NULL,
  descripcion text NOT NULL, clase_division varchar(50) NULL, peligro_secundario text NULL, nombre_tecnico text NULL,
  fecha_inicio_vigencia date NULL, fecha_fin_vigencia date NULL
);
CREATE INDEX IF NOT EXISTS materiales_peligrosos_clave_idx ON sat.materiales_peligrosos (clave_material_peligroso_sat);
CREATE TABLE IF NOT EXISTS sat.tipos_embalaje (
  clave_tipo_embalaje_sat varchar(20) PRIMARY KEY, descripcion text NOT NULL,
  fecha_inicio_vigencia date NULL, fecha_fin_vigencia date NULL
);
CREATE INDEX IF NOT EXISTS bienes_transportados_descripcion_idx ON sat.bienes_transportados (lower(descripcion));
CREATE INDEX IF NOT EXISTS materiales_peligrosos_descripcion_idx ON sat.materiales_peligrosos (lower(descripcion));
CREATE INDEX IF NOT EXISTS tipos_embalaje_descripcion_idx ON sat.tipos_embalaje (lower(descripcion));
CREATE TEMP TABLE _cp_bienes (LIKE sat.bienes_transportados) ON COMMIT DROP;
COPY _cp_bienes FROM STDIN WITH (FORMAT text, NULL '\N');
